// Kannada numerology texts. Keys match numerologyTextsEn in numerology_texts.dart.
const numerologyTextsKn = <String, String>{
  // What each number type represents
  'type.lifePath': 'ಜೀವನ ಪಥ ಸಂಖ್ಯೆಯು ಸಂಪೂರ್ಣ ಜನ್ಮ ದಿನಾಂಕದಿಂದ ಬರುತ್ತದೆ. ಸಂಪ್ರದಾಯದಂತೆ ಇದನ್ನು ಜೀವನದುದ್ದಕ್ಕೂ ಸಾಗುವ ಮುಖ್ಯ ಆಶಯವೆಂದು ಓದಲಾಗುತ್ತದೆ: ಮತ್ತೆ ಮತ್ತೆ ಎದುರಾಗುವ ಪಾಠಗಳು, ಆಸಕ್ತಿಗಳು ಮತ್ತು ದಿಕ್ಕು.',
  'type.birthday': 'ಹುಟ್ಟುಹಬ್ಬ ಸಂಖ್ಯೆಯು ತಿಂಗಳ ಯಾವ ದಿನ ಹುಟ್ಟಿದಿರಿ ಎಂಬುದರಿಂದ ಮಾತ್ರ ಬರುತ್ತದೆ. ನೀವು ಜೀವನ ಪಥಕ್ಕೆ ತರುವ ವಿಶೇಷ ಪ್ರತಿಭೆ ಅಥವಾ ಕೆಲಸ ಮಾಡುವ ರೀತಿ ಎಂದು ಇದನ್ನು ಓದಲಾಗುತ್ತದೆ.',
  'type.mulank': 'ಮೂಲಾಂಕ (ಮೂಲ ಸಂಖ್ಯೆ) ಹುಟ್ಟಿದ ದಿನದಿಂದ ಬರುತ್ತದೆ. ಭಾರತೀಯ ಸಂಖ್ಯಾಶಾಸ್ತ್ರ ಇದನ್ನು ನಿಮ್ಮ ಮೂಲ ಸ್ವಭಾವವೆಂದು ಓದುತ್ತದೆ: ದಿನನಿತ್ಯ ನೀವು ಹೇಗೆ ಯೋಚಿಸುತ್ತೀರಿ ಮತ್ತು ವರ್ತಿಸುತ್ತೀರಿ ಎಂಬುದು.',
  'type.bhagyank': 'ಭಾಗ್ಯಾಂಕ (ಭಾಗ್ಯ ಸಂಖ್ಯೆ) ಜನ್ಮ ದಿನಾಂಕದ ಎಲ್ಲಾ ಅಂಕೆಗಳಿಂದ ಬರುತ್ತದೆ. ಭಾರತೀಯ ಸಂಖ್ಯಾಶಾಸ್ತ್ರ ಇದನ್ನು ಜೀವನದ ವಿಶಾಲ ದಿಕ್ಕು ಮತ್ತು ಅದರೊಂದಿಗೆ ಬರುವ ಅವಕಾಶಗಳ ಸ್ವರೂಪವೆಂದು ಓದುತ್ತದೆ.',
  'type.expression': 'ಅಭಿವ್ಯಕ್ತಿ ಸಂಖ್ಯೆಯು ಪೂರ್ಣ ಹೆಸರಿನ ಪ್ರತಿಯೊಂದು ಅಕ್ಷರದಿಂದ ಬರುತ್ತದೆ. ಇದನ್ನು ನಿಮ್ಮ ಸಹಜ ಸಾಮರ್ಥ್ಯಗಳು ಮತ್ತು ಕೆಲಸ ಹಾಗೂ ಜೀವನದಲ್ಲಿ ನೀವು ಅವನ್ನು ವ್ಯಕ್ತಪಡಿಸುವ ರೀತಿ ಎಂದು ಓದಲಾಗುತ್ತದೆ.',
  'type.soulUrge': 'ಆತ್ಮ ಸಂಖ್ಯೆಯು ಹೆಸರಿನ ಸ್ವರಗಳಿಂದ ಬರುತ್ತದೆ. ಇದನ್ನು ಒಳಗಿನ ಪ್ರೇರಣೆ ಎಂದು ಓದಲಾಗುತ್ತದೆ: ನೀವು ಹೊರಗೆ ತೋರಿಸದಿದ್ದರೂ ಆಳದಲ್ಲಿ ನಿಜವಾಗಿ ಬಯಸುವುದು.',
  'type.personality': 'ವ್ಯಕ್ತಿತ್ವ ಸಂಖ್ಯೆಯು ಹೆಸರಿನ ವ್ಯಂಜನಗಳಿಂದ ಬರುತ್ತದೆ. ಇದನ್ನು ನಿಮ್ಮ ಬಗ್ಗೆ ಇತರರಲ್ಲಿ ಮೂಡುವ ಮೊದಲ ಅಭಿಪ್ರಾಯ ಮತ್ತು ಇತರರು ಸಾಮಾನ್ಯವಾಗಿ ನಿಮ್ಮನ್ನು ಹೇಗೆ ಕಾಣುತ್ತಾರೆ ಎಂಬುದಾಗಿ ಓದಲಾಗುತ್ತದೆ.',
  'type.chaldeanName': 'ಕಾಲ್ಡಿಯನ್ ಹೆಸರಿನ ಸಂಖ್ಯೆಯು ಅಕ್ಷರಗಳ ಧ್ವನಿಯನ್ನು ಆಧರಿಸಿದ ಹಳೆಯ ಅಕ್ಷರ ಪಟ್ಟಿಯನ್ನು ಬಳಸುತ್ತದೆ. ನಿಮ್ಮನ್ನು ಜನರು ಗುರುತಿಸುವ ಹೆಸರಿನ ಒಟ್ಟಾರೆ ಕಂಪನವೆಂದು ಇದನ್ನು ಓದಲಾಗುತ್ತದೆ.',

  // Fuller meanings: strengths, challenges, practical guidance
  'num.1.strengths': 'ಉಪಕ್ರಮ, ಸ್ವಾತಂತ್ರ್ಯ, ಕೆಲಸಗಳನ್ನು ಆರಂಭಿಸುವ ಮತ್ತು ಮುನ್ನಡೆಸುವ ಧೈರ್ಯ.',
  'num.1.challenges': 'ಅಸಹನೆ, ಹಠ ಅಥವಾ ಇತರರ ಸಹಾಯ ಸ್ವೀಕರಿಸಲು ಹಿಂಜರಿಕೆ ಕಾಣಬಹುದು.',
  'num.1.guidance': 'ಹೊಸ ಕೆಲಸಗಳಲ್ಲಿ ಮುಂದಾಳತ್ವ ವಹಿಸಿ, ಆದರೆ ನಿರ್ಧರಿಸುವ ಮೊದಲು ಇತರರ ಮಾತು ಕೇಳಿ ಮತ್ತು ಶ್ರೇಯವನ್ನು ಹಂಚಿಕೊಳ್ಳಿ.',
  'num.2.strengths': 'ಜಾಣ್ಮೆಯ ನಡವಳಿಕೆ, ತಾಳ್ಮೆ, ಇತರರ ಬಗ್ಗೆ ಸೂಕ್ಷ್ಮತೆ ಮತ್ತು ಸಹಕಾರದ ಸಹಜ ಗುಣ.',
  'num.2.challenges': 'ಅತಿಯಾದ ಸೂಕ್ಷ್ಮತೆ, ಅನಿರ್ಧಾರ ಅಥವಾ ಎಲ್ಲರನ್ನೂ ಮೆಚ್ಚಿಸುವ ಅತಿಯಾದ ಹಂಬಲ ಕಾಣಬಹುದು.',
  'num.2.guidance':
      'ಪಾಲುದಾರಿಕೆ ಮತ್ತು ತಂಡದ ಕೆಲಸ ನಿಮಗೆ ಹೊಂದುತ್ತದೆ; ಅಗತ್ಯವಿದ್ದಾಗ ಶಾಂತವಾಗಿ "ಇಲ್ಲ" ಎನ್ನುವುದನ್ನು ಅಭ್ಯಾಸ ಮಾಡಿ.',
  'num.3.strengths': 'ಸೃಜನಶೀಲತೆ, ಉಲ್ಲಾಸದ ಅಭಿವ್ಯಕ್ತಿ, ಮಾತಿನಲ್ಲಿ ಮತ್ತು ಜನರೊಂದಿಗಿನ ಒಡನಾಟದಲ್ಲಿ ಚತುರತೆ.',
  'num.3.challenges': 'ಹಲವಾರು ಆಸಕ್ತಿಗಳಲ್ಲಿ ಶಕ್ತಿ ಹಂಚಿಹೋಗಬಹುದು; ದಿನಚರಿಯಿಂದ ದೂರ ಉಳಿಯಬಹುದು.',
  'num.3.guidance': 'ಪೂರ್ಣಗೊಳಿಸಲು ಒಂದೆರಡು ಯೋಜನೆಗಳನ್ನು ಆರಿಸಿಕೊಳ್ಳಿ, ಮತ್ತು ನಿಮ್ಮ ಮಾತನ್ನು ಇತರರನ್ನು ಹುರಿದುಂಬಿಸಲು ಬಳಸಿ.',
  'num.4.strengths': 'ವಿಶ್ವಾಸಾರ್ಹತೆ, ಕ್ರಮಬದ್ಧತೆ, ಕಠಿಣ ಪರಿಶ್ರಮ ಮತ್ತು ವ್ಯಾವಹಾರಿಕವಾಗಿ ಸಮಸ್ಯೆ ಬಗೆಹರಿಸುವ ಸಾಮರ್ಥ್ಯ.',
  'num.4.challenges': 'ಕಟ್ಟುನಿಟ್ಟು, ಅತಿಯಾದ ದುಡಿಮೆ ಅಥವಾ ಹಠಾತ್ ಬದಲಾವಣೆಗೆ ಪ್ರತಿರೋಧ ಕಾಣಬಹುದು.',
  'num.4.guidance': 'ಹಂತ ಹಂತವಾಗಿ ಕಟ್ಟಿ, ಸ್ವಲ್ಪ ನಮ್ಯತೆ ಇಟ್ಟುಕೊಳ್ಳಿ, ಮತ್ತು ಕೆಲಸದಷ್ಟೇ ಗಂಭೀರವಾಗಿ ವಿಶ್ರಾಂತಿಯನ್ನೂ ಯೋಜಿಸಿ.',
  'num.5.strengths': 'ಕುತೂಹಲ, ಹೊಂದಿಕೊಳ್ಳುವ ಗುಣ, ಚುರುಕಾದ ಆಲೋಚನೆ ಮತ್ತು ಸಂವಹನ.',
  'num.5.challenges': 'ಚಡಪಡಿಕೆ, ಆತುರದ ನಿರ್ಧಾರಗಳು, ಬದ್ಧರಾಗಿ ಉಳಿಯುವಲ್ಲಿ ತೊಂದರೆ.',
  'num.5.guidance': 'ಬದಲಾವಣೆಯನ್ನು ಸ್ವಾಗತಿಸಿ, ಆದರೆ ಕೆಲವು ಸ್ಥಿರ ಅಭ್ಯಾಸಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿ; ದೊಡ್ಡ ಜೋಖಿಮಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳುವ ಮುನ್ನ ಎರಡು ಬಾರಿ ಯೋಚಿಸಿ.',
  'num.6.strengths': 'ಕಾಳಜಿ, ಜವಾಬ್ದಾರಿ, ಸೌಂದರ್ಯಪ್ರಜ್ಞೆ ಮತ್ತು ಮನೆಯಲ್ಲಿ ಸಾಮರಸ್ಯ.',
  'num.6.challenges': 'ಇತರರಿಗಾಗಿ ಅತಿಯಾದ ಹೊರೆ ಹೊರುವುದು, ಚಿಂತೆ ಅಥವಾ ನಿಯಂತ್ರಿಸುವ ಪ್ರವೃತ್ತಿ ಕಾಣಬಹುದು.',
  'num.6.guidance': 'ನಿಮ್ಮನ್ನು ನಿರ್ಲಕ್ಷಿಸದೆ ಇತರರ ಸೇವೆ ಮಾಡಿ; ಜನರು ತಮ್ಮ ಸಮಸ್ಯೆಗಳನ್ನು ತಾವೇ ಬಗೆಹರಿಸಿಕೊಳ್ಳಲು ಬಿಡಿ.',
  'num.7.strengths': 'ಆಳವಾದ ಚಿಂತನೆ, ಸಂಶೋಧನೆ, ಅಂತರ್ಬೋಧೆ ಮತ್ತು ಸಮೃದ್ಧ ಅಂತರಂಗ ಜೀವನ.',
  'num.7.challenges': 'ಎಲ್ಲರಿಂದ ದೂರ ಸರಿಯುವುದು, ಅತಿಯಾಗಿ ಯೋಚಿಸುವುದು ಅಥವಾ ಇತರರನ್ನು ನಂಬಲು ಕಷ್ಟವಾಗುವುದು ಕಾಣಬಹುದು.',
  'num.7.guidance': 'ಅಧ್ಯಯನ ಮತ್ತು ಏಕಾಂತಕ್ಕೆ ಸಮಯ ಮಾಡಿಕೊಳ್ಳಿ, ಮತ್ತು ನಂಬಿಕಸ್ಥ ಕೆಲವರೊಂದಿಗೆ ನಿಮ್ಮ ಆಲೋಚನೆಗಳನ್ನು ಹಂಚಿಕೊಳ್ಳಿ.',
  'num.8.strengths': 'ಶಿಸ್ತು, ಮಹತ್ವಾಕಾಂಕ್ಷೆ, ತಾಳ್ಮೆ ಮತ್ತು ಸಂಪನ್ಮೂಲಗಳನ್ನು ನಿರ್ವಹಿಸುವ ಕೌಶಲ.',
  'num.8.challenges': 'ಅತಿಯಾದ ಗಂಭೀರತೆ, ಕೆಲಸದಲ್ಲೇ ಮುಳುಗಿರುವುದು, ಅಥವಾ ಫಲಿತಾಂಶ ನಿಧಾನವಾಗಿ ಬರುತ್ತದೆ ಎಂಬ ಭಾವನೆ ಕಾಣಬಹುದು.',
  'num.8.guidance': 'ಸ್ಥಿರ ಪ್ರಯತ್ನಕ್ಕೆ ಕಾಲಕ್ರಮೇಣ ಫಲ ಸಿಗುತ್ತದೆ ಎಂದು ಸಂಪ್ರದಾಯ ಹೇಳುತ್ತದೆ; ಕೆಲಸವನ್ನು ಕುಟುಂಬ ಮತ್ತು ಆರೋಗ್ಯದೊಂದಿಗೆ ಸಮತೋಲನಗೊಳಿಸಿ.',
  'num.9.strengths': 'ಕರುಣೆ, ಧೈರ್ಯ, ಉದಾರತೆ ಮತ್ತು ವಿಶಾಲ ದೃಷ್ಟಿಕೋನ.',
  'num.9.challenges': 'ಅಸಹನೆ, ಬೇಗ ಕೋಪಗೊಳ್ಳುವುದು, ಅಥವಾ ದಣಿಯುವವರೆಗೂ ಕೊಡುತ್ತಲೇ ಇರುವುದು ಕಾಣಬಹುದು.',
  'num.9.guidance':
      'ನಿಮಗೆ ಮುಖ್ಯವೆನಿಸುವ ಉದ್ದೇಶಗಳತ್ತ ಶಕ್ತಿಯನ್ನು ಹರಿಸಿ; ಆರಂಭಿಸಿದ್ದನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ ಮತ್ತು ಘನತೆಯಿಂದ ಕೈಬಿಡಲು ಕಲಿಯಿರಿ.',
  'num.11.strengths': 'ಅಂತರ್ಬೋಧೆ, ಸ್ಫೂರ್ತಿ ಮತ್ತು ಇತರರನ್ನು ಮೇಲೆತ್ತುವ ಸಾಮರ್ಥ್ಯ.',
  'num.11.challenges': 'ನರಗಳ ಒತ್ತಡ, ಆತ್ಮಸಂಶಯ ಮತ್ತು ತನ್ನ ಬಗ್ಗೆಯೇ ಅತಿ ಹೆಚ್ಚಿನ ನಿರೀಕ್ಷೆಗಳು.',
  'num.11.guidance': 'ಆಲೋಚನೆಗಳನ್ನು ದಿನನಿತ್ಯದ ಆಚರಣೆಯಲ್ಲಿ ನೆಲೆಗೊಳಿಸಿ; ಸಾಮಾನ್ಯ ದಿನಗಳಲ್ಲಿ 2ರ ಗುಣಗಳು ಅನ್ವಯಿಸುತ್ತವೆ.',
  'num.22.strengths': 'ದೀರ್ಘಕಾಲ ಉಳಿಯುವಂಥದ್ದನ್ನು ಕಟ್ಟಲು ದೂರದೃಷ್ಟಿ ಮತ್ತು ವ್ಯಾವಹಾರಿಕ ಕೌಶಲದ ಸಂಗಮ.',
  'num.22.challenges': 'ಬಹಳಷ್ಟು ಸಾಧಿಸಬೇಕೆಂಬ ಒತ್ತಡ; ದೊಡ್ಡ ಯೋಜನೆಗಳ ಭಾರ ಹೆಚ್ಚೆನಿಸಬಹುದು.',
  'num.22.guidance': 'ದೊಡ್ಡ ಗುರಿಗಳನ್ನು ಸಣ್ಣ ಹೆಜ್ಜೆಗಳಾಗಿ ವಿಂಗಡಿಸಿ; ಸಾಮಾನ್ಯ ದಿನಗಳಲ್ಲಿ 4ರ ಗುಣಗಳು ಅನ್ವಯಿಸುತ್ತವೆ.',
  'num.33.strengths': 'ಕರುಣೆಯಿಂದ ಕಲಿಸುವುದು, ಉಪಶಮನ ನೀಡುವುದು ಮತ್ತು ಇತರರ ಸೇವೆ.',
  'num.33.challenges': 'ಸ್ವತ್ಯಾಗ, ಇತರರ ಹೊರೆಯನ್ನು ತಾವೇ ಹೊರುವುದು, ಪರಿಪೂರ್ಣತೆಯ ಹಠ.',
  'num.33.guidance': 'ಇತರರಂತೆ ನಿಮ್ಮನ್ನೂ ನೋಡಿಕೊಳ್ಳಿ; ಸಾಮಾನ್ಯ ದಿನಗಳಲ್ಲಿ 6ರ ಗುಣಗಳು ಅನ್ವಯಿಸುತ್ತವೆ.',

  // Mulank-Bhagyank pair
  'pair.intro': 'ಮೂಲಾಂಕ ನೀವು ದಿನನಿತ್ಯ ಹೇಗೆ ವರ್ತಿಸುತ್ತೀರಿ ಎಂಬುದನ್ನು ತೋರಿಸುತ್ತದೆ; ಭಾಗ್ಯಾಂಕ ಜೀವನದ ವಿಶಾಲ ದಿಕ್ಕನ್ನು ತೋರಿಸುತ್ತದೆ. ಭಾರತೀಯ ಸಂಖ್ಯಾಶಾಸ್ತ್ರ ಇವೆರಡರ ಅಧಿಪತಿ ಗ್ರಹಗಳನ್ನು ಶಾಸ್ತ್ರೀಯ ನೈಸರ್ಗಿಕ ಗ್ರಹಮೈತ್ರಿಯ ಆಧಾರದ ಮೇಲೆ ಹೋಲಿಸುತ್ತದೆ.',
  'pair.same': 'ಎರಡೂ ಸಂಖ್ಯೆಗಳಿಗೆ ಒಂದೇ ಗ್ರಹ, ಆದ್ದರಿಂದ ಸಂಪ್ರದಾಯದಂತೆ ಅದರ ಗುಣಗಳು ಬಲಗೊಂಡಿವೆ ಎಂದು ಓದಲಾಗುತ್ತದೆ: ಅದರ ಶಕ್ತಿಗಳು ಹೆಚ್ಚುತ್ತವೆ, ಹಾಗೆಯೇ ಅದರ ಸಾಮಾನ್ಯ ಸವಾಲುಗಳೂ.',
  'pair.friendly': 'ಅಧಿಪತಿ ಗ್ರಹಗಳು ನೈಸರ್ಗಿಕ ಮಿತ್ರರು, ಆದ್ದರಿಂದ ಸಂಪ್ರದಾಯದಂತೆ ನಿಮ್ಮ ಸ್ವಭಾವ (ಮೂಲಾಂಕ) ಮತ್ತು ಜೀವನದ ದಿಕ್ಕು (ಭಾಗ್ಯಾಂಕ) ಪರಸ್ಪರ ಪೂರಕವಾಗಿವೆ ಎಂದು ಓದಲಾಗುತ್ತದೆ.',
  'pair.neutral': 'ಗ್ರಹಗಳು ಪರಸ್ಪರ ಸಮ (ತಟಸ್ಥ), ಅಥವಾ ಒಂದನ್ನೊಂದು ಬೇರೆ ಬೇರೆ ರೀತಿಯಲ್ಲಿ ಕಾಣುತ್ತವೆ; ಆದ್ದರಿಂದ ಸಂಪ್ರದಾಯದಂತೆ ಈ ಜೋಡಿಯನ್ನು ನಿಭಾಯಿಸಬಹುದಾದುದು ಎಂದು ಓದಲಾಗುತ್ತದೆ: ಎರಡು ಪ್ರಭಾವಗಳು ಒಂದಕ್ಕೊಂದು ಹೆಚ್ಚು ನೆರವಾಗುವುದೂ ಇಲ್ಲ, ಅಡ್ಡಿಯಾಗುವುದೂ ಇಲ್ಲ.',
  'pair.challenging': 'ಶಾಸ್ತ್ರೀಯ ಕೋಷ್ಟಕದಲ್ಲಿ ಈ ಗ್ರಹಗಳು ನೈಸರ್ಗಿಕ ಶತ್ರುಗಳು, ಆದ್ದರಿಂದ ಸ್ವಭಾವ ಮತ್ತು ಜೀವನದ ದಿಕ್ಕಿನ ನಡುವೆ ಸ್ವಲ್ಪ ಆಂತರಿಕ ಸೆಳೆತ ಇರಬಹುದೆಂದು ಸಂಪ್ರದಾಯ ಸೂಚಿಸುತ್ತದೆ. ಇದನ್ನು ಅಶುಭ ಸೂಚನೆಯಾಗಿ ಅಲ್ಲ, ಪ್ರಜ್ಞಾಪೂರ್ವಕವಾಗಿ ಸಮತೋಲನಗೊಳಿಸಬೇಕಾದ ವಿಷಯವಾಗಿ ಓದಲಾಗುತ್ತದೆ.',
  'pair.nodesNote': 'ರಾಹು (4) ಮತ್ತು ಕೇತು (7) ಶಾಸ್ತ್ರೀಯ ಮೈತ್ರಿ ಕೋಷ್ಟಕದಲ್ಲಿ ಇಲ್ಲ. ಈ ಆ್ಯಪ್ ನಂತರದ ಕಾಲದ ಒಂದು ಸಾಮಾನ್ಯ ಪದ್ಧತಿಯನ್ನು ಬಳಸುತ್ತದೆ (ರಾಹು: ಮಿತ್ರರು ಬುಧ, ಶುಕ್ರ, ಶನಿ; ಕೇತು: ಮಿತ್ರರು ಕುಜ, ಶುಕ್ರ, ಶನಿ), ಮತ್ತು ಈ ಬಗ್ಗೆ ವಿವಿಧ ಪರಂಪರೆಗಳಲ್ಲಿ ಭಿನ್ನಾಭಿಪ್ರಾಯಗಳಿವೆ.',

  // Lo Shu grid
  'loshu.intro': 'ಲೋ ಶು ಚೌಕವು ಪ್ರಾಚೀನ ಚೀನೀ ಮಾಯಾಚೌಕ; ಇದರ ಪ್ರತಿಯೊಂದು ಅಡ್ಡಸಾಲು, ಲಂಬಸಾಲು ಮತ್ತು ಕರ್ಣದ ಮೊತ್ತ 15. ಜನ್ಮ ದಿನಾಂಕದ ಪ್ರತಿಯೊಂದು ಅಂಕೆಯನ್ನು ಅದರ ಮನೆಯಲ್ಲಿ ಇಡಲಾಗುತ್ತದೆ (ವಿನ್ಯಾಸ 4-9-2 / 3-5-7 / 8-1-6); ಸೊನ್ನೆಗಳನ್ನು ಪರಿಗಣಿಸುವುದಿಲ್ಲ.',
  'loshu.indianNote': 'ಸಾಮಾನ್ಯ ಭಾರತೀಯ ಪದ್ಧತಿಯಲ್ಲಿ ಭಾಗ್ಯಾಂಕವನ್ನೂ ಸೇರಿಸಲಾಗುತ್ತದೆ; ಮೂಲಾಂಕವನ್ನೂ ಸೇರಿಸಲಾಗುತ್ತದೆ, ಆದರೆ ಹುಟ್ಟಿದ ದಿನ 1-9, 10, 20 ಅಥವಾ 30 ಆಗಿದ್ದರೆ ಸೇರಿಸುವುದಿಲ್ಲ (ಆಗ ಅದು ಈಗಾಗಲೇ ಚೌಕದಲ್ಲಿರುತ್ತದೆ). ದಿನಾಂಕದ ಚೌಕವನ್ನು ಮಾತ್ರ ನೋಡಲು ಈ ಆಯ್ಕೆಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ.',
  'loshu.missing.1': '1 ಇಲ್ಲ: ನಿಮ್ಮನ್ನು ಮತ್ತು ನಿಮ್ಮ ಭಾವನೆಗಳನ್ನು ವ್ಯಕ್ತಪಡಿಸಲು ಪ್ರಜ್ಞಾಪೂರ್ವಕ ಪ್ರಯತ್ನ ಬೇಕಾಗಬಹುದು.',
  'loshu.missing.2': '2 ಇಲ್ಲ: ತಾಳ್ಮೆ ಮತ್ತು ಇತರರ ಬಗ್ಗೆ ಸೂಕ್ಷ್ಮತೆಯನ್ನು ಬೆಳೆಸಿಕೊಳ್ಳಬೇಕಾಗಬಹುದು.',
  'loshu.missing.3': '3 ಇಲ್ಲ: ಕಲ್ಪನಾಶಕ್ತಿ ಮತ್ತು ನಿಮ್ಮ ಆಲೋಚನೆಗಳಲ್ಲಿ ವಿಶ್ವಾಸಕ್ಕೆ ಪ್ರೋತ್ಸಾಹ ಬೇಕಾಗಬಹುದು.',
  'loshu.missing.4': '4 ಇಲ್ಲ: ಕ್ರಮ, ಶಿಸ್ತು ಮತ್ತು ದಿನಚರಿಯತ್ತ ಉದ್ದೇಶಪೂರ್ವಕ ಗಮನ ಬೇಕಾಗಬಹುದು.',
  'loshu.missing.5': '5 ಇಲ್ಲ: ಭಾವನಾತ್ಮಕ ಸಮತೋಲನ ಮತ್ತು ಸ್ಥಿರ ಏಕಾಗ್ರತೆಗೆ ಅಭ್ಯಾಸ ಬೇಕಾಗಬಹುದು.',
  'loshu.missing.6': '6 ಇಲ್ಲ: ಮನೆ, ಕುಟುಂಬದ ಜವಾಬ್ದಾರಿಗಳು ಮತ್ತು ಸುಖ-ಸೌಕರ್ಯಗಳ ಬಗ್ಗೆ ಹೆಚ್ಚಿನ ಕಾಳಜಿ ಬೇಕಾಗಬಹುದು.',
  'loshu.missing.7': '7 ಇಲ್ಲ: ಪಾಠಗಳು ಹೆಚ್ಚಾಗಿ ಅನುಭವದ ಮೂಲಕ ಬರುತ್ತವೆ; ಆತ್ಮಾವಲೋಕನಕ್ಕೆ ಸಮಯ ಕೊಡುವುದು ನೆರವಾಗುತ್ತದೆ.',
  'loshu.missing.8': '8 ಇಲ್ಲ: ಸೂಕ್ಷ್ಮ ವಿವರಗಳತ್ತ ಗಮನ ಮತ್ತು ಎಚ್ಚರಿಕೆಯ ಹಣಕಾಸು ನಿರ್ವಹಣೆಗೆ ಪ್ರಯತ್ನ ಬೇಕಾಗಬಹುದು.',
  'loshu.missing.9': '9 ಇಲ್ಲ: ಮಹತ್ವಾಕಾಂಕ್ಷೆ ಮತ್ತು ವಿಶಾಲ ಉದ್ದೇಶವನ್ನು ಪ್ರಜ್ಞಾಪೂರ್ವಕವಾಗಿ ಪೋಷಿಸಬೇಕಾಗಬಹುದು.',
  'loshu.repeat.1.2': '1 ಎರಡು ಬಾರಿ: ಸಂಪ್ರದಾಯದಂತೆ ಸಮತೋಲಿತ, ಸ್ಪಷ್ಟ ಸ್ವ-ಅಭಿವ್ಯಕ್ತಿ ಎಂದು ಓದಲಾಗುತ್ತದೆ.',
  'loshu.repeat.1.3':
      '1 ಮೂರು ಅಥವಾ ಹೆಚ್ಚು ಬಾರಿ: ಹೆಚ್ಚು ಮಾತನಾಡಬಹುದು, ಅಥವಾ ಆಳವಾದ ಭಾವನೆಗಳನ್ನು ಮಾತಿನಲ್ಲಿ ಹೇಳಲು ಕಷ್ಟವಾಗಬಹುದು.',
  'loshu.repeat.2.2': '2 ಎರಡು ಬಾರಿ: ಬಲವಾದ ಅಂತರ್ಬೋಧೆ ಮತ್ತು ಸೂಕ್ಷ್ಮತೆ; ಜನರನ್ನು ಚೆನ್ನಾಗಿ ಅರಿಯುವವರು.',
  'loshu.repeat.2.3':
      '2 ಮೂರು ಅಥವಾ ಹೆಚ್ಚು ಬಾರಿ: ಬೇಗ ನೊಂದುಕೊಳ್ಳಬಹುದು; ನಿಮ್ಮ ಭಾವನಾತ್ಮಕ ಶಕ್ತಿಯನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳುವುದು ನೆರವಾಗುತ್ತದೆ.',
  'loshu.repeat.3.2': '3 ಎರಡು ಬಾರಿ: ಸಮೃದ್ಧ ಕಲ್ಪನಾಶಕ್ತಿ ಮತ್ತು ಸೃಜನಶೀಲ, ಚುರುಕಾದ ಮನಸ್ಸು.',
  'loshu.repeat.3.3':
      '3 ಮೂರು ಅಥವಾ ಹೆಚ್ಚು ಬಾರಿ: ಆಲೋಚನೆಗಳು ಚದುರಬಹುದು ಅಥವಾ ಚಿಂತೆಯತ್ತ ತಿರುಗಬಹುದು; ವಿಷಯಗಳನ್ನು ಬರೆದಿಡುವುದು ನೆರವಾಗುತ್ತದೆ.',
  'loshu.repeat.4.2': '4 ಎರಡು ಬಾರಿ: ಬಹಳ ವ್ಯವಸ್ಥಿತ ಮತ್ತು ಶ್ರಮಜೀವಿ, ವ್ಯಾವಹಾರಿಕ ಕೌಶಲಗಳಲ್ಲಿ ನಿಪುಣರು.',
  'loshu.repeat.4.3': '4 ಮೂರು ಅಥವಾ ಹೆಚ್ಚು ಬಾರಿ: ಕಟ್ಟುನಿಟ್ಟಾಗಬಹುದು ಅಥವಾ ಭೌತಿಕ ವಿಷಯಗಳತ್ತ ಅತಿಯಾಗಿ ಗಮನ ಹರಿಸಬಹುದು.',
  'loshu.repeat.5.2': '5 ಎರಡು ಬಾರಿ: ಬಲವಾದ ಉತ್ಸಾಹ ಮತ್ತು ದೃಢನಿಶ್ಚಯ.',
  'loshu.repeat.5.3': '5 ಮೂರು ಅಥವಾ ಹೆಚ್ಚು ಬಾರಿ: ಆತುರದಲ್ಲಿ ವರ್ತಿಸಬಹುದು ಅಥವಾ ಮಾತನಾಡಬಹುದು; ಪ್ರತಿಕ್ರಿಯಿಸುವ ಮುನ್ನ ಒಂದು ಕ್ಷಣ ನಿಲ್ಲುವುದು ನೆರವಾಗುತ್ತದೆ.',
  'loshu.repeat.6.2': '6 ಎರಡು ಬಾರಿ: ಮನೆ ಮತ್ತು ಕುಟುಂಬದ ಬಗ್ಗೆ ಆಳವಾದ ಕಾಳಜಿ.',
  'loshu.repeat.6.3': '6 ಮೂರು ಅಥವಾ ಹೆಚ್ಚು ಬಾರಿ: ಪ್ರೀತಿಪಾತ್ರರ ಬಗ್ಗೆ ಚಿಂತಿಸಬಹುದು ಅಥವಾ ಅತಿಯಾದ ರಕ್ಷಣಾಭಾವ ತೋರಬಹುದು.',
  'loshu.repeat.7.2': '7 ಎರಡು ಬಾರಿ: ಅನುಭವದಿಂದ ಆಳವಾಗಿ ಕಲಿಯುವವರು; ಅಧ್ಯಯನ ಮತ್ತು ಆಂತರಿಕ ಪ್ರಶ್ನೆಗಳತ್ತ ಒಲವು.',
  'loshu.repeat.7.3':
      '7 ಮೂರು ಅಥವಾ ಹೆಚ್ಚು ಬಾರಿ: ಜೀವನದ ಪಾಠಗಳು ಕೆಲವೊಮ್ಮೆ ಭಾರವೆನಿಸಬಹುದು; ವಿಶ್ರಾಂತಿ ಮತ್ತು ಇತರರ ಬೆಂಬಲ ಮುಖ್ಯ.',
  'loshu.repeat.8.2': '8 ಎರಡು ಬಾರಿ: ಕ್ರಮಬದ್ಧ, ವಿವರಗಳತ್ತ ಗಮನವಿರುವ ಮತ್ತು ವಿಶ್ವಾಸಾರ್ಹ.',
  'loshu.repeat.8.3': '8 ಮೂರು ಅಥವಾ ಹೆಚ್ಚು ಬಾರಿ: ಚಡಪಡಿಕೆ ಅಥವಾ ಪರಿಪೂರ್ಣತೆಯ ಹಠ ಕಾಣಬಹುದು.',
  'loshu.repeat.9.2': '9 ಎರಡು ಬಾರಿ: ಆದರ್ಶವಾದಿ, ಮಹತ್ವಾಕಾಂಕ್ಷಿ ಮತ್ತು ಬೇಗ ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವವರು.',
  'loshu.repeat.9.3': '9 ಮೂರು ಅಥವಾ ಹೆಚ್ಚು ಬಾರಿ: ಇತರರ ಬಗ್ಗೆ ಟೀಕಾತ್ಮಕ ಅಥವಾ ಅಸಹನೆಯುಳ್ಳವರಾಗಬಹುದು.',
  'loshu.plane.mental.name': 'ಮಾನಸಿಕ ಸ್ತರ',
  'loshu.plane.mental.meaning':
      'ಮೇಲಿನ ಅಡ್ಡಸಾಲು ಪೂರ್ಣ: ಸಂಪ್ರದಾಯದಂತೆ ಉತ್ತಮ ಸ್ಮರಣಶಕ್ತಿ, ವಿಶ್ಲೇಷಣೆ ಮತ್ತು ಯೋಜನೆಯೊಂದಿಗೆ ಸಂಬಂಧ.',
  'loshu.plane.emotional.name': 'ಭಾವನಾತ್ಮಕ ಸ್ತರ',
  'loshu.plane.emotional.meaning': 'ನಡುವಿನ ಅಡ್ಡಸಾಲು ಪೂರ್ಣ: ಸಂಪ್ರದಾಯದಂತೆ ಭಾವನಾತ್ಮಕ ಆಳ ಮತ್ತು ಸಹಾನುಭೂತಿಯೊಂದಿಗೆ ಸಂಬಂಧ.',
  'loshu.plane.practical.name': 'ವ್ಯಾವಹಾರಿಕ ಸ್ತರ',
  'loshu.plane.practical.meaning':
      'ಕೆಳಗಿನ ಅಡ್ಡಸಾಲು ಪೂರ್ಣ: ಸಂಪ್ರದಾಯದಂತೆ ವ್ಯಾವಹಾರಿಕ ಕೌಶಲ ಮತ್ತು ಕೆಲಸಗಳನ್ನು ಮುಗಿಸುವ ಸಾಮರ್ಥ್ಯದೊಂದಿಗೆ ಸಂಬಂಧ.',
  'loshu.plane.thought.name': 'ಚಿಂತನಾ ಸ್ತರ',
  'loshu.plane.thought.meaning': 'ಎಡ ಲಂಬಸಾಲು ಪೂರ್ಣ: ಸಂಪ್ರದಾಯದಂತೆ ಆಲೋಚನೆಗಳು, ಯೋಜನೆ ಮತ್ತು ಸಂಘಟನೆಯೊಂದಿಗೆ ಸಂಬಂಧ.',
  'loshu.plane.will.name': 'ಇಚ್ಛಾಶಕ್ತಿ ಸ್ತರ',
  'loshu.plane.will.meaning': 'ನಡುವಿನ ಲಂಬಸಾಲು ಪೂರ್ಣ: ಸಂಪ್ರದಾಯದಂತೆ ದೃಢನಿಶ್ಚಯ ಮತ್ತು ಛಲದೊಂದಿಗೆ ಸಂಬಂಧ.',
  'loshu.plane.action.name': 'ಕ್ರಿಯಾ ಸ್ತರ',
  'loshu.plane.action.meaning': 'ಬಲ ಲಂಬಸಾಲು ಪೂರ್ಣ: ಸಂಪ್ರದಾಯದಂತೆ ಆಲೋಚನೆಗಳನ್ನು ಕಾರ್ಯರೂಪಕ್ಕೆ ತರುವುದರೊಂದಿಗೆ ಸಂಬಂಧ.',
  'loshu.plane.golden.name': 'ಸುವರ್ಣ ಸ್ತರ',
  'loshu.plane.golden.meaning': 'ಕರ್ಣ 4-5-6 ಪೂರ್ಣ: ಕೆಲವು ಭಾರತೀಯ ಸಂಖ್ಯಾಶಾಸ್ತ್ರಜ್ಞರು ಇದನ್ನು "ಸುವರ್ಣ ಯೋಗ" ಎನ್ನುತ್ತಾರೆ ಮತ್ತು ಸ್ಥಿರ ಪ್ರಯತ್ನ ಪ್ರಗತಿಯಾಗಿ ಮಾರ್ಪಡುವುದೆಂದು ಓದುತ್ತಾರೆ.',
  'loshu.plane.silver.name': 'ರಜತ ಸ್ತರ',
  'loshu.plane.silver.meaning': 'ಕರ್ಣ 2-5-8 ಪೂರ್ಣ: ಕೆಲವು ಭಾರತೀಯ ಸಂಖ್ಯಾಶಾಸ್ತ್ರಜ್ಞರು ಇದನ್ನು "ರಜತ ಯೋಗ" ಎನ್ನುತ್ತಾರೆ ಮತ್ತು ಅಂತರ್ಬೋಧೆ ಹಾಗೂ ಆಸ್ತಿ ವಿಷಯಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸುತ್ತಾರೆ.',

  // Chaldean compound numbers (Cheiro's tradition, in neutral words)
  'compound.intro': 'ಕೀರೋ ಅವರ ಪರಂಪರೆಯಲ್ಲಿ, ಒಂದಂಕಿಗೆ ಇಳಿಸುವ ಮುನ್ನದ ಕಾಲ್ಡಿಯನ್ ಮೊತ್ತಕ್ಕೆ (10-52) ತನ್ನದೇ ಅರ್ಥವಿದೆ; ಇದನ್ನು ಒಂದಂಕಿಯ ಜೊತೆಗೆ ಓದಲಾಗುತ್ತದೆ.',
  'compound.10':
      '"ಅದೃಷ್ಟ ಚಕ್ರ" ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ: ಗೌರವ, ಆತ್ಮವಿಶ್ವಾಸ ಮತ್ತು ಸರದಿಯಂತೆ ಏಳುಬೀಳು; ಜನರಿಗೆ ಪರಿಚಿತವಾಗುವ ಹೆಸರು.',
  'compound.11': 'ಕಾಣದ ಅಡೆತಡೆಗಳ ಬಗ್ಗೆ ಮತ್ತು ಯಾರನ್ನು ನಂಬುತ್ತೀರಿ ಎಂಬುದರ ಬಗ್ಗೆ ಎಚ್ಚರ ವಹಿಸಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ; ಶ್ರದ್ಧೆ ಮತ್ತು ತಾಳ್ಮೆಗೆ ಒತ್ತು ನೀಡಲಾಗುತ್ತದೆ.',
  'compound.12':
      'ಇತರರಿಗಾಗಿ ತ್ಯಾಗದೊಂದಿಗೆ ಸಂಬಂಧ; ಜನರಿಗೆ ನೆರವಾಗುವಾಗಲೂ ನಿಮ್ಮ ಸ್ವಂತ ಹಿತವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ.',
  'compound.13': 'ಬದಲಾವಣೆ, ರೂಪಾಂತರ ಮತ್ತು ಅಂತ್ಯಗಳ ನಂತರದ ಹೊಸ ಆರಂಭಗಳೊಂದಿಗೆ ಸಂಬಂಧ; ವಿವೇಕದಿಂದ ಬಳಸಬೇಕಾದ ಶಕ್ತಿ.',
  'compound.14': 'ಚಲನೆ, ವ್ಯಾಪಾರ ಮತ್ತು ಜನರೊಂದಿಗಿನ ವ್ಯವಹಾರಗಳು; ಊಹಾತ್ಮಕ ಹೂಡಿಕೆ ಮತ್ತು ಇತರರ ತೀರ್ಮಾನವನ್ನು ಅವಲಂಬಿಸುವುದರ ಬಗ್ಗೆ ಎಚ್ಚರ ವಹಿಸಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ.',
  'compound.15': 'ಆಕರ್ಷಣೆ, ವಾಕ್ಚಾತುರ್ಯ ಮತ್ತು ಕಲಾತ್ಮಕ ಪ್ರತಿಭೆ; ಇತರರಿಂದ ನೆರವು ಸಿಗುತ್ತದೆ. ಇದನ್ನು ಪ್ರಾಮಾಣಿಕವಾಗಿ ಬಳಸಬೇಕೆಂದು ಸಂಪ್ರದಾಯ ಹೇಳುತ್ತದೆ.',
  'compound.16': 'ಯೋಜನೆಗಳಲ್ಲಿ ಅಥವಾ ಸ್ಥಾನದಲ್ಲಿ ಹಠಾತ್ ಬದಲಾವಣೆಗಳೊಂದಿಗೆ ಸಂಬಂಧ; ಎಚ್ಚರಿಕೆಯ ಯೋಜನೆ ಮತ್ತು ವಿನಯವನ್ನು ಸಂಪ್ರದಾಯ ಸಲಹೆ ಮಾಡುತ್ತದೆ.',
  'compound.17':
      '"ಜ್ಞಾನಿಗಳ ತಾರೆ" ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ: ಶಾಂತಿ, ಪ್ರೀತಿ ಮತ್ತು ಕಷ್ಟಗಳನ್ನು ಮೀರಿ ಮೇಲೇರುವುದು; ನೆನಪಿನಲ್ಲಿ ಉಳಿಯುವ ಹೆಸರು.',
  'compound.18':
      'ಭೌತಿಕ ಮತ್ತು ಆಧ್ಯಾತ್ಮಿಕ ಗುರಿಗಳ ನಡುವಿನ ಸೆಳೆತದೊಂದಿಗೆ ಸಂಬಂಧ; ವಿವಾದಗಳಲ್ಲಿ ಎಚ್ಚರ ವಹಿಸಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ.',
  'compound.19': '"ಸ್ವರ್ಗದ ರಾಜಕುಮಾರ" ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ: ಸಂತೋಷ, ಗೌರವ ಮತ್ತು ಯಶಸ್ಸು; ಅತ್ಯಂತ ಅನುಕೂಲಕರ ಸಂಖ್ಯೆಗಳಲ್ಲಿ ಒಂದು.',
  'compound.20': '"ಜಾಗೃತಿ" ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ: ಹೊಸ ಉದ್ದೇಶ ಮತ್ತು ಯೋಜನೆಗಳತ್ತ ಕರೆ; ಭೌತಿಕ ಲಾಭಕ್ಕಿಂತ ಹೆಚ್ಚಾಗಿ ಆಂತರಿಕ ಬೆಳವಣಿಗೆಯಾಗಿ ಓದಲಾಗುತ್ತದೆ.',
  'compound.21': '"ಜ್ಞಾನಿಗಳ ಕಿರೀಟ" ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ: ಪ್ರಗತಿ ಮತ್ತು ಮನ್ನಣೆ, ಹೆಚ್ಚಾಗಿ ದೀರ್ಘ ಪ್ರಯತ್ನದ ನಂತರ.',
  'compound.22': 'ಭ್ರಮೆಗಳು, ಅತಿಯಾದ ನಂಬಿಕೆ ಮತ್ತು ಇತರರ ತಪ್ಪು ಸಲಹೆಗಳ ಬಗ್ಗೆ ಎಚ್ಚರ ವಹಿಸಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ; ನಿಮ್ಮ ಸ್ವಂತ ವಿವೇಚನೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿ.',
  'compound.23': '"ಸಿಂಹದ ರಾಜನಕ್ಷತ್ರ" ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ: ಯೋಜನೆಗಳಲ್ಲಿ ಯಶಸ್ಸು ಮತ್ತು ಅಧಿಕಾರದಲ್ಲಿರುವವರಿಂದ ನೆರವು.',
  'compound.24': 'ಅನುಕೂಲಕರ: ಉನ್ನತ ಸ್ಥಾನದಲ್ಲಿರುವವರಿಂದ ನೆರವು, ಮತ್ತು ಪ್ರೀತಿ ಹಾಗೂ ಪಾಲುದಾರಿಕೆಯಲ್ಲಿ ಆತ್ಮೀಯತೆ.',
  'compound.25': 'ಅನುಭವ ಮತ್ತು ಅವಲೋಕನದಿಂದ ಗಳಿಸಿದ ಶಕ್ತಿ; ಆರಂಭದಲ್ಲಿ ಪರೀಕ್ಷೆಗಳು, ನಂತರ ಸ್ಥಿರತೆ.',
  'compound.26': 'ಪಾಲುದಾರಿಕೆ, ಊಹಾತ್ಮಕ ಹೂಡಿಕೆ ಮತ್ತು ಇತರರ ಸಲಹೆಗಳ ಬಗ್ಗೆ ಎಚ್ಚರ ವಹಿಸಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ; ಒಪ್ಪಂದಗಳನ್ನು ಸ್ಪಷ್ಟವಾಗಿಡಿ.',
  'compound.27': '"ರಾಜದಂಡ" ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ: ನಿಮ್ಮ ಸ್ವಂತ ಚಿಂತನೆ ಮತ್ತು ಸೃಜನಶೀಲ ಕೆಲಸದಿಂದ ಅಧಿಕಾರ ಮತ್ತು ಪ್ರತಿಫಲ.',
  'compound.28': 'ಭರವಸೆ ಮತ್ತು ಪ್ರಗತಿ ಇದ್ದರೂ, ತಪ್ಪಾದ ಕಡೆ ಇಟ್ಟ ನಂಬಿಕೆಯಿಂದ ಅವು ಕೈತಪ್ಪಬಹುದು; ಎಚ್ಚರಿಕೆಯ ಒಪ್ಪಂದಗಳು ಮತ್ತು ಭವಿಷ್ಯಕ್ಕಾಗಿ ಉಳಿತಾಯವನ್ನು ಸಂಪ್ರದಾಯ ಸಲಹೆ ಮಾಡುತ್ತದೆ.',
  'compound.29': 'ಆಪ್ತ ಸಂಬಂಧಗಳಲ್ಲಿ ಮತ್ತು ಯಾರನ್ನು ಅವಲಂಬಿಸಬೇಕು ಎಂದು ಆರಿಸುವಲ್ಲಿ ಎಚ್ಚರ ವಹಿಸಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ.',
  'compound.30': 'ಚಿಂತನಶೀಲ ಆತ್ಮಾವಲೋಕನ ಮತ್ತು ಮಾನಸಿಕ ಶಕ್ತಿ; ಶುಭವೂ ಅಲ್ಲ ಅಶುಭವೂ ಅಲ್ಲ, ದೃಷ್ಟಿಕೋನವನ್ನು ಅವಲಂಬಿಸಿದೆ.',
  'compound.31': '30ರಂತೆಯೇ, ಆದರೆ ಹೆಚ್ಚು ಅಂತರ್ಮುಖಿ; ಏಕಾಂತವನ್ನು ಇಷ್ಟಪಡಬಹುದಾದ ಚಿಂತಕ.',
  'compound.32': 'ಜನರನ್ನು ಒಗ್ಗೂಡಿಸುವುದು ಮತ್ತು ಮನವೊಲಿಕೆಯೊಂದಿಗೆ ಸಂಬಂಧ; ನಿಮ್ಮ ಸ್ವಂತ ವಿವೇಚನೆಗೆ ಬದ್ಧರಾಗಿದ್ದಾಗ ಅನುಕೂಲಕರ.',
  'compound.33': 'ಕೀರೋ ಇದನ್ನು 24ರಂತೆ ಓದುತ್ತಾರೆ: ಉನ್ನತ ಸ್ಥಾನದಲ್ಲಿರುವವರಿಂದ ನೆರವು ಮತ್ತು ಸಂಬಂಧಗಳಲ್ಲಿ ಆತ್ಮೀಯತೆ.',
  'compound.34': 'ಕೀರೋ ಇದನ್ನು 25ರಂತೆ ಓದುತ್ತಾರೆ: ಅನುಭವದಿಂದ ಗಳಿಸಿದ ಶಕ್ತಿ; ಆರಂಭದಲ್ಲಿ ಪರೀಕ್ಷೆಗಳು, ನಂತರ ಸ್ಥಿರತೆ.',
  'compound.35':
      'ಕೀರೋ ಇದನ್ನು 26ರಂತೆ ಓದುತ್ತಾರೆ: ಪಾಲುದಾರಿಕೆ ಮತ್ತು ಊಹಾತ್ಮಕ ಹೂಡಿಕೆಯ ಬಗ್ಗೆ ಎಚ್ಚರ ವಹಿಸಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ.',
  'compound.36': 'ಕೀರೋ ಇದನ್ನು 27ರಂತೆ ಓದುತ್ತಾರೆ: ನಿಮ್ಮ ಸ್ವಂತ ಚಿಂತನೆ ಮತ್ತು ಕೆಲಸದಿಂದ ಅಧಿಕಾರ ಮತ್ತು ಪ್ರತಿಫಲ.',
  'compound.37': 'ಸ್ನೇಹ, ಪ್ರೀತಿ ಮತ್ತು ಪಾಲುದಾರಿಕೆಗೆ ಅನುಕೂಲಕರ; ಸಾಮರಸ್ಯದ ಒಡನಾಟಗಳು.',
  'compound.38':
      'ಕೀರೋ ಇದನ್ನು 29ರಂತೆ ಓದುತ್ತಾರೆ: ಯಾರನ್ನು ಅವಲಂಬಿಸಬೇಕು ಎಂದು ಆರಿಸುವಲ್ಲಿ ಎಚ್ಚರ ವಹಿಸಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ.',
  'compound.39': 'ಕೀರೋ ಇದನ್ನು 30ರಂತೆ ಓದುತ್ತಾರೆ: ಚಿಂತನಶೀಲ ಆತ್ಮಾವಲೋಕನ; ದೃಷ್ಟಿಕೋನವನ್ನು ಅವಲಂಬಿಸಿದೆ.',
  'compound.40': 'ಕೀರೋ ಇದನ್ನು 31ರಂತೆ ಓದುತ್ತಾರೆ: ಅಂತರ್ಮುಖಿ, ಚಿಂತನಶೀಲ, ಏಕಾಂತವನ್ನು ಇಷ್ಟಪಡಬಹುದು.',
  'compound.41': 'ಕೀರೋ ಇದನ್ನು 32ರಂತೆ ಓದುತ್ತಾರೆ: ಜನರನ್ನು ಒಗ್ಗೂಡಿಸುವುದು; ಸ್ವತಂತ್ರ ವಿವೇಚನೆಯೊಂದಿಗೆ ಅನುಕೂಲಕರ.',
  'compound.42': 'ಕೀರೋ ಇದನ್ನು 24ರಂತೆ ಓದುತ್ತಾರೆ: ಉನ್ನತ ಸ್ಥಾನದಲ್ಲಿರುವವರಿಂದ ನೆರವು ಮತ್ತು ಸಂಬಂಧಗಳಲ್ಲಿ ಆತ್ಮೀಯತೆ.',
  'compound.43':
      'ಏರುಪೇರು ಮತ್ತು ವಿರೋಧದೊಂದಿಗೆ ಸಂಬಂಧ; ತಾಳ್ಮೆ, ನಮ್ಯತೆ ಮತ್ತು ಅನಗತ್ಯ ಸಂಘರ್ಷದಿಂದ ದೂರವಿರಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ.',
  'compound.44':
      'ಕೀರೋ ಇದನ್ನು 26ರಂತೆ ಓದುತ್ತಾರೆ: ಪಾಲುದಾರಿಕೆ ಮತ್ತು ಊಹಾತ್ಮಕ ಹೂಡಿಕೆಯ ಬಗ್ಗೆ ಎಚ್ಚರ ವಹಿಸಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ.',
  'compound.45': 'ಕೀರೋ ಇದನ್ನು 27ರಂತೆ ಓದುತ್ತಾರೆ: ನಿಮ್ಮ ಸ್ವಂತ ಚಿಂತನೆ ಮತ್ತು ಕೆಲಸದಿಂದ ಅಧಿಕಾರ ಮತ್ತು ಪ್ರತಿಫಲ.',
  'compound.46': 'ಕೀರೋ ಇದನ್ನು 37ರಂತೆ ಓದುತ್ತಾರೆ: ಸ್ನೇಹ, ಪ್ರೀತಿ ಮತ್ತು ಪಾಲುದಾರಿಕೆಗೆ ಅನುಕೂಲಕರ.',
  'compound.47':
      'ಕೀರೋ ಇದನ್ನು 29ರಂತೆ ಓದುತ್ತಾರೆ: ಯಾರನ್ನು ಅವಲಂಬಿಸಬೇಕು ಎಂದು ಆರಿಸುವಲ್ಲಿ ಎಚ್ಚರ ವಹಿಸಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ.',
  'compound.48': 'ಕೀರೋ ಇದನ್ನು 30ರಂತೆ ಓದುತ್ತಾರೆ: ಚಿಂತನಶೀಲ ಆತ್ಮಾವಲೋಕನ; ದೃಷ್ಟಿಕೋನವನ್ನು ಅವಲಂಬಿಸಿದೆ.',
  'compound.49': 'ಕೀರೋ ಇದನ್ನು 31ರಂತೆ ಓದುತ್ತಾರೆ: ಅಂತರ್ಮುಖಿ, ಚಿಂತನಶೀಲ, ಏಕಾಂತವನ್ನು ಇಷ್ಟಪಡಬಹುದು.',
  'compound.50': 'ಕೀರೋ ಇದನ್ನು 32ರಂತೆ ಓದುತ್ತಾರೆ: ಜನರನ್ನು ಒಗ್ಗೂಡಿಸುವುದು; ಸ್ವತಂತ್ರ ವಿವೇಚನೆಯೊಂದಿಗೆ ಅನುಕೂಲಕರ.',
  'compound.51': 'ದಿಟ್ಟ ಕ್ರಿಯೆ ಮತ್ತು ಹಠಾತ್ ಏಳಿಗೆಯೊಂದಿಗೆ ಸಂಬಂಧ; ಪ್ರತಿಸ್ಪರ್ಧಿಗಳ ಬಗ್ಗೆ ಗಮನವಿಟ್ಟು ಎಚ್ಚರದಿಂದ ಮುಂದುವರಿಯಲು ಸಂಪ್ರದಾಯ ಸಲಹೆ ನೀಡುತ್ತದೆ.',
  'compound.52': 'ಕೀರೋ ಇದನ್ನು 43ರಂತೆ ಓದುತ್ತಾರೆ: ಏರುಪೇರಿನ ಸಮಯಗಳಲ್ಲಿ ತಾಳ್ಮೆ ಮತ್ತು ನಮ್ಯತೆಯನ್ನು ಸಂಪ್ರದಾಯ ಸಲಹೆ ಮಾಡುತ್ತದೆ.',

  // Personal year / month / day
  'cycle.year': 'ವೈಯಕ್ತಿಕ ವರ್ಷ = ಹುಟ್ಟಿದ ದಿನ + ಹುಟ್ಟಿದ ತಿಂಗಳು + ಪ್ರಸ್ತುತ ವರ್ಷ, ಒಂದಂಕಿಗೆ ಇಳಿಸಿ. ಒಂಬತ್ತು ವರ್ಷಗಳ ಚಕ್ರದೊಳಗೆ, ಆ ವರ್ಷದ ನಿಮ್ಮ ಮುಖ್ಯ ಆಶಯವೆಂದು ಇದನ್ನು ಓದಲಾಗುತ್ತದೆ.',
  'cycle.month': 'ವೈಯಕ್ತಿಕ ತಿಂಗಳು = ವೈಯಕ್ತಿಕ ವರ್ಷ + ಪ್ರಸ್ತುತ ತಿಂಗಳು, ಒಂದಂಕಿಗೆ ಇಳಿಸಿ. ವರ್ಷದೊಳಗಿನ ಕಿರು ಅವಧಿಯ ಆಶಯ.',
  'cycle.day': 'ವೈಯಕ್ತಿಕ ದಿನ = ವೈಯಕ್ತಿಕ ತಿಂಗಳು + ಆ ದಿನದ ದಿನಾಂಕ, ಒಂದಂಕಿಗೆ ಇಳಿಸಿ. ಒಂದು ದಿನದ ಧಾಟಿ.',
  'cycle.1': 'ಹೊಸ ಆರಂಭಗಳು: ಯೋಜನೆಗಳನ್ನು ಆರಂಭಿಸಿ, ಉಪಕ್ರಮ ತೆಗೆದುಕೊಳ್ಳಿ, ಬೀಜ ಬಿತ್ತಿ.',
  'cycle.2': 'ತಾಳ್ಮೆ ಮತ್ತು ಸಹಕಾರ: ಸಂಬಂಧಗಳು, ನಿಧಾನ ಪ್ರಗತಿ, ಆಲಿಸುವುದು.',
  'cycle.3': 'ಅಭಿವ್ಯಕ್ತಿ: ಸೃಜನಶೀಲತೆ, ಸಾಮಾಜಿಕ ಜೀವನ, ಸಂವಹನ ಮತ್ತು ಸಂತೋಷ.',
  'cycle.4': 'ಅಡಿಪಾಯ: ಸ್ಥಿರ ಕೆಲಸ, ವ್ಯವಸ್ಥೆಗೊಳಿಸುವುದು, ಆರೋಗ್ಯಕರ ದಿನಚರಿ.',
  'cycle.5': 'ಬದಲಾವಣೆ: ಪ್ರಯಾಣ, ವೈವಿಧ್ಯ, ಸ್ವಾತಂತ್ರ್ಯ; ಹೊಂದಿಕೊಳ್ಳುವ ಮನೋಭಾವ ಇಟ್ಟುಕೊಳ್ಳಿ.',
  'cycle.6': 'ಮನೆ ಮತ್ತು ಜವಾಬ್ದಾರಿ: ಕುಟುಂಬ, ಕಾಳಜಿ, ಬದ್ಧತೆಗಳು.',
  'cycle.7': 'ಆತ್ಮಾವಲೋಕನ: ಅಧ್ಯಯನ, ವಿಶ್ರಾಂತಿ, ಆಂತರಿಕ ಕೆಲಸ ಮತ್ತು ಪುನರ್ವಿಮರ್ಶೆ.',
  'cycle.8': 'ಪ್ರಯತ್ನ ಮತ್ತು ಫಲ: ವೃತ್ತಿ, ಹಣಕಾಸು, ವ್ಯಾವಹಾರಿಕ ನಿರ್ಧಾರಗಳು.',
  'cycle.9': 'ಪೂರ್ಣತೆ: ಮುಗಿಸುವುದು, ಬಿಟ್ಟುಕೊಡುವುದು, ಉದಾರತೆ; ಮುಂದೆ ಬರುವುದಕ್ಕೆ ಜಾಗ ಮಾಡಿಕೊಡುವುದು.',

  // About the methods
  'about.pythagorean': 'ಪೈಥಾಗೊರಿಯನ್ (ಪಾಶ್ಚಾತ್ಯ): A-Z ಅಕ್ಷರಗಳಿಗೆ ಕ್ರಮವಾಗಿ 1-9 ಮೌಲ್ಯಗಳು (A=1 ... I=9, J=1 ...). ಇದರಿಂದ ಜೀವನ ಪಥ, ಅಭಿವ್ಯಕ್ತಿ, ಆತ್ಮ ಮತ್ತು ವ್ಯಕ್ತಿತ್ವ ಸಂಖ್ಯೆಗಳು ಬರುತ್ತವೆ; ಮಾಸ್ಟರ್ ಸಂಖ್ಯೆಗಳಾದ 11, 22 ಮತ್ತು 33 ಅನ್ನು ಇಳಿಸದೆ ಹಾಗೆಯೇ ಉಳಿಸಲಾಗುತ್ತದೆ.',
  'about.chaldean': 'ಕಾಲ್ಡಿಯನ್: ಅಕ್ಷರಗಳ ಧ್ವನಿಯ ಆಧಾರದ ಮೇಲೆ ಅವಕ್ಕೆ 1-8 ಮೌಲ್ಯಗಳನ್ನು ನೀಡುವ ಹಳೆಯ ಪದ್ಧತಿ (9 ಅನ್ನು ಪವಿತ್ರವೆಂದು ಪರಿಗಣಿಸಿ ಯಾವ ಅಕ್ಷರಕ್ಕೂ ನೀಡುವುದಿಲ್ಲ). ಒಂದಂಕಿಗೆ ಇಳಿಸುವ ಮುನ್ನದ ಮೊತ್ತವನ್ನು ಕೀರೋ ಅವರ ಪರಂಪರೆಯಲ್ಲಿ ಸಂಯುಕ್ತ ಸಂಖ್ಯೆಯಾಗಿ ಓದಲಾಗುತ್ತದೆ.',
  'about.indian': 'ಭಾರತೀಯ ಸಂಖ್ಯಾಶಾಸ್ತ್ರ: ಮೂಲಾಂಕ (ಹುಟ್ಟಿದ ದಿನ) ಮತ್ತು ಭಾಗ್ಯಾಂಕ (ಸಂಪೂರ್ಣ ದಿನಾಂಕ) ಪ್ರತಿಯೊಂದೂ ಒಂದು ಗ್ರಹಕ್ಕೆ ಸಂಬಂಧಿಸಿದೆ: 1 ಸೂರ್ಯ, 2 ಚಂದ್ರ, 3 ಗುರು, 4 ರಾಹು, 5 ಬುಧ, 6 ಶುಕ್ರ, 7 ಕೇತು, 8 ಶನಿ, 9 ಕುಜ. ಇವನ್ನು ಯಾವಾಗಲೂ 1-9ಕ್ಕೆ ಇಳಿಸಲಾಗುತ್ತದೆ.',
  'about.loshu': 'ಲೋ ಶು: ಪ್ರಾಚೀನ ಚೀನೀ 3×3 ಮಾಯಾಚೌಕ. ಯಾವ ಸಂಖ್ಯೆಗಳು ಬಲವಾಗಿವೆ, ಪುನರಾವರ್ತನೆಯಾಗಿವೆ ಅಥವಾ ಇಲ್ಲ ಎಂದು ನೋಡಲು ಜನ್ಮ ದಿನಾಂಕದ ಅಂಕೆಗಳನ್ನು ಇದರಲ್ಲಿ ಇಡಲಾಗುತ್ತದೆ; ಭಾರತೀಯ ಸಂಖ್ಯಾಶಾಸ್ತ್ರಜ್ಞರು ಸಾಮಾನ್ಯವಾಗಿ ಮೂಲಾಂಕ ಮತ್ತು ಭಾಗ್ಯಾಂಕವನ್ನೂ ಸೇರಿಸುತ್ತಾರೆ.',
  'about.honest': 'ಸಂಖ್ಯಾಶಾಸ್ತ್ರ ಒಂದು ಸಾಂಪ್ರದಾಯಿಕ, ಸಾಂಕೇತಿಕ ಪದ್ಧತಿ. ಸಂಖ್ಯೆಗಳು ಘಟನೆಗಳನ್ನು ಅಥವಾ ಸ್ವಭಾವವನ್ನು ಮುನ್ಸೂಚಿಸುತ್ತವೆ ಎಂಬುದಕ್ಕೆ ಯಾವುದೇ ವೈಜ್ಞಾನಿಕ ಪುರಾವೆ ಇಲ್ಲ. ಇದನ್ನು ಆತ್ಮಾವಲೋಕನಕ್ಕೆ ಒಂದು ಪ್ರೇರಣೆಯಾಗಿ ಓದಿ; ಯಾವುದೇ ಸಂಖ್ಯೆಗಿಂತ ನಿಮ್ಮ ಆಯ್ಕೆಗಳು ಮತ್ತು ಪ್ರಯತ್ನಗಳು ಹೆಚ್ಚು ಮುಖ್ಯ.',
};
